static int write_dbbt ( struct boot_config * boot_cfg , struct dbbt_block * dbbt , void * dbbt_data_page ) { int i ; loff_t off , to ; size_t size ; struct mtd_info * mtd ; int ret ; mtd = boot_cfg -> mtd ; off = boot_cfg -> search_area_size_in_bytes ; for ( i = 0 ; i < g_boot_search_count ; i ++ ) { if ( mtd_block_isbad ( mtd , off ) ) { printf ( "Block %d is bad, skipped\n" , ( int ) ( i + CONV_TO_BLOCKS ( off ) ) ) ; off += mtd -> erasesize ; continue ; } ret = nand_write ( mtd , off , & size , ( u_char * ) dbbt ) ; printf ( "NAND DBBT write to 0x%llx offset 0x%zx written: %s\n" , off , size , ret ?"ERROR" : "OK" ) ; if ( ret ) { return ret ; } if ( dbbt -> dbbtpages > 0 ) { to = off + 4 * mtd -> writesize ; ret = nand_write ( mtd , to , & size , dbbt_data_page ) ; printf ( "DBBT data write to 0x%llx offset 0x%zx written: %s\n" , to , size , ret ?"ERROR" : "OK" ) ; if ( ret ) { return ret ; } } off += g_boot_search_stride ; } return 0 ; } 